Pi=math.pi;Tau=math.pi*2;Inf=math.huge;Deg=math.pi/180;Sin=math.sin;Cos=math.cos;Tan=math.tan;Acos=math.acos;Asin=math.asin;Atan=math.atan;Sqrt=math.sqrt;Max=math.max;Min=math.min;Floor=math.floor;Ceil=math.ceil;Abs=math.abs;function Clamp(a,b,c)return Min(Max(a,b),c)end;function Lerp(d,e,f)return d+(e-d)*f end;function Map(f,d,e,g,h)return(f-d)/(e-d)*(h-g)+g end;function Round(d)return Floor(d+0.5)end;function Vec(i,j,k)return{x=i,y=j,z=k}end;function Add(l,m)return{x=l.x+m.x,y=l.y+m.y,z=l.z+m.z}end;function Sub(l,m)return{x=l.x-m.x,y=l.y-m.y,z=l.z-m.z}end;function Scale(l,n)return{x=l.x*n,y=l.y*n,z=l.z*n}end;function Dot(l,m)return l.x*m.x+l.y*m.y+l.z*m.z end;function Cross(l,m)return{x=l.y*m.z-l.z*m.y,y=l.z*m.x-l.x*m.z,z=l.x*m.y-l.y*m.x}end;function Len(l)return Sqrt(l.x*l.x+l.y*l.y+l.z*l.z)end;function SetLen(l,n)return Scale(Norm(l),n)end;function Norm(l)return Len(l)~=0 and Scale(l,1/Len(l))or{x=0,y=0,z=0}end;function Lerp(l,m,f)return Add(l,Scale(Sub(m,l),f))end;function IJK(o,p,q)local r,s,t=Cos(o),Cos(p),Cos(q)local u,v,w=Sin(o),Sin(p),Sin(q)return Vec(Vec(s*t,s*w,-v),Vec(-r*w+u*v*t,r*t+u*v*w,u*s),Vec(r*v*t+u*w,r*v*w-u*t,r*s))end;function Local(l,x)return Vec(Dot(l,x.x),Dot(l,x.y),Dot(l,x.z))end;function Global(l,x)return Add(Scale(x.x,l.x),Add(Scale(x.y,l.y),Scale(x.z,l.z)))end;function Sphere(l)return Vec(Atan(l.x,l.z),Atan(l.y,l.z),Len(l))end;function Cartesian(l)local y=Cos(l.x)<0 and-1 or 1;local z=Vec(Sin(l.x)*Cos(l.y)*y,Sin(l.y)*Cos(l.x)*y,Cos(l.x)*Cos(l.y)*y)return Scale(Norm(z),l.z)end;launched=false;state=0;debug_state=0;elapsed=0;target=Vec(0,0,0)waypoints={}aimpoint=Vec(0,0,0)terminal_ticks=0;radar_enabled=false;GUIDE_DELAY=property.getNumber("Guidance Delay")BOOST_DELAY=property.getNumber("Booster Delay")MODE=property.getNumber("Mode")EJECT_DIRECTION=property.getNumber("Eject Direction")EJECT_DURATION=property.getNumber("Eject Duration")ALTITUDE_MODE=property.getBool("Altitude Mode")ROLL_CONTROL=property.getBool("Active Roll Control")CRUISE_PAT