 radar_enabled=true end;guidance=Sphere(Local(aimpoint,self.IJK))end;if launched and ROLL_CONTROL then guidance.z=-self.roll else guidance.z=0 end;output.setNumber(1,Clamp(guidance.x/Pi*X_GAIN+X_TRIM,-1,1))output.setNumber(2,Clamp(guidance.y/Pi*Y_GAIN+Y_TRIM,-1,1))output.setNumber(3,Clamp(guidance.z*R_GAIN+R_TRIM,-1,1))output.setNumber(4,debug_state)output.setNumber(8,Round(Len(g_delta)))end